package com.example.lending.domain;

import org.junit.jupiter.api.Test;

import java.time.LocalDate;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class LoanLateFeeTest {

    private static final LocalDate LOANED_AT = LocalDate.of(2026, 1, 1);
    private static final LocalDate DUE_AT = LocalDate.of(2026, 1, 15);

    @Test
    void returning_on_the_due_date_has_no_late_fee() {
        Loan loan = startLoan();

        loan.returnOn(DUE_AT);

        assertThat(loan.overdueDays()).isZero();
        assertThat(loan.lateFee()).isZero();
    }

    @Test
    void each_day_past_the_due_date_costs_100() {
        Loan oneDayLate = startLoan();
        oneDayLate.returnOn(DUE_AT.plusDays(1));
        assertThat(oneDayLate.overdueDays()).isEqualTo(1);
        assertThat(oneDayLate.lateFee()).isEqualTo(100);

        Loan fiveDaysLate = startLoan();
        fiveDaysLate.returnOn(DUE_AT.plusDays(5));
        assertThat(fiveDaysLate.overdueDays()).isEqualTo(5);
        assertThat(fiveDaysLate.lateFee()).isEqualTo(500);
    }

    @Test
    void overdue_days_of_an_unreturned_loan_cannot_be_computed() {
        Loan loan = startLoan();

        assertThatThrownBy(loan::overdueDays).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void returning_before_the_loan_date_is_rejected() {
        Loan loan = startLoan();

        assertThatThrownBy(() -> loan.returnOn(LOANED_AT.minusDays(1)))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private static Loan startLoan() {
        return Loan.start(UUID.randomUUID(), UUID.randomUUID(), LOANED_AT);
    }
}

